const tabId = 725790064;
// Check the editor DOM inside the iframe or page
const editorDetails = await browserjs(tabId, () => {
  // Let's find any iframe
  const iframes = Array.from(document.querySelectorAll('iframe'));
  let iframeWin = null;
  let iframeDoc = null;
  for (const f of iframes) {
    try {
      if (f.contentDocument && f.contentDocument.body) {
        iframeDoc = f.contentDocument;
        break;
      }
    } catch(e) {}
  }
  const doc = iframeDoc || document;
  const cm = doc.querySelector('.CodeMirror');
  const textarea = doc.querySelector('textarea');
  const contentEdit = doc.querySelector('[contenteditable="true"]');
  return {
    hasIframeDoc: !!iframeDoc,
    hasCM: !!cm,
    hasTextarea: !!textarea,
    hasContentEdit: !!contentEdit,
    cmText: cm?.CodeMirror?.getValue ? cm.CodeMirror.getValue() : null,
    bodyText: doc.body.innerText.slice(0, 300)
  };
});
console.log("Editor details:", JSON.stringify(editorDetails, null, 2));

